fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // Ensure all input vectors have the same length
    let n = s1.len();
    if n != s2.len() || n != s3.len() {
        return Vec::new(); // or panic!("Input vectors must have the same length");
    }

    // Create a new vector with the capacity of 3n
    let mut res = Vec::with_capacity(3 * n);

    // Interleave the elements
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}